import { useId } from "react";
import type { ComponentType, ReactNode, SVGProps } from "react";

export interface TechLogo {
  name: string;
  color: string;
  Icon: ComponentType<SVGProps<SVGSVGElement>>;
}

type IconProps = SVGProps<SVGSVGElement>;

function makeIcon(
  viewBox: string,
  children: ReactNode | ((uid: string) => ReactNode)
) {
  function TechIcon({ className, ...props }: IconProps) {
    const uid = useId().replace(/:/g, "");
    const content = typeof children === "function" ? children(uid) : children;
    return (
      <svg viewBox={viewBox} aria-hidden="true" className={className} {...props}>
        {content}
      </svg>
    );
  }
  TechIcon.displayName = "TechIcon";
  return TechIcon;
}

